args.command:
cd /workspace && cat > forum_body.json <<'EOF'
{"content":"Checked the Route 9 log (Eastgate, Thu 22 Oct 2026). Twelve parcels were loaded (P-901 to P-912) and the table has 13 scan rows, but only 12 distinct parcels: P-904 appears twice - 10:31 'Not delivered' (no answer; card left) and 15:52 'Delivered' (second attempt, signed R. Iqbal). Counting distinct parcels, all twelve carry a Delivered status, and the latest delivery scan is P-912 at 16:58, before the 17:00 service level. The end-of-day entries corroborate completeness (van back at 17:20, 0 parcels returned, 0 carried over), and telematics confirms a stop at each address at the scan time. The failed first attempt on P-904 does not affect the claim, since it was redelivered the same day inside the window. Uncertainties: the log is the only document in the case; P-902 (left with reception) and P-906 (safe place: porch) rest on the driver's entry rather than a signature, though the service level concerns delivery time, not proof type. On the record as submitted the claim holds, so no challenge from me."}
EOF
curl -s -X POST "$VERACITY_URL/v1/episodes/VR-488564/forum/messages" -H "Content-Type: application/json" -H "Idempotency-Key: vr488564-forum-1" --data-binary @forum_body.json | python3 -c "
import json,sys; d=json.load(sys.stdin); print('seq',d['sequence'],d['sender_id'],d['content_hash'])
"

cd /workspace && date -u; curl -s "$VERACITY_URL/v1/episodes/VR-488564" | python3 -c "
import json,sys; d=json.load(sys.stdin); print('phase:',d['phase'],'| evidence:',d['evidence'])
"; curl -s "$VERACITY_URL/v1/episodes/VR-488564/forum/messages" | python3 -c "
import json,sys; d=json.load(sys.stdin); print(len(d['messages']),'forum messages from',[m['sender_id'] for m in d['messages']])
"

cd /workspace && curl -s "$VERACITY_URL/v1/episodes/VR-488564/forum/messages" | python3 -c "
import json,sys; d=json.load(sys.stdin)
for m in d['messages']:
    if m['sequence']==3: print(m['content'])
"

cd /workspace && date -u; curl -s "$VERACITY_URL/v1/episodes/VR-488564" | python3 -c "
import json,sys; d=json.load(sys.stdin)
print('phase:',d['phase'],'| evidence:',d['evidence'],'| challenge_deadline:',d['challenge_deadline'])
print('content unchanged:', d['content'])
print('content_hash:',d['content_hash'])
"; echo '--- forum/chats ---'; curl -s "$VERACITY_URL/v1/episodes/VR-488564/forum/messages" | python3 -c "
import json,sys; d=json.load(sys.stdin); print('forum:',len(d['messages']),'msgs',[m['sender_id'] for m in d['messages']])
"; curl -s "$VERACITY_URL/v1/episodes/VR-488564/chats" | head -c 200; echo; curl -s "$VERACITY_URL/v1/episodes/VR-488564/balances" | python3 -c "
import json,sys; d=json.load(sys.stdin); print('my credits:',d['withdrawal_credits']['challenger'])
"
